def solve(inputs: dict) -> float:
    import re
    # Try to extract from structured inputs first
    def find(keys):
        for k in keys:
            for kk in inputs:
                if kk.lower() == k:
                    return inputs[kk]
        return None
    start = find(['start','x','x0','initial','begin'])
    a = find(['a','mult','multiplier'])
    c = find(['c','inc','increment','add'])
    m = find(['m','mod','modulus'])
    rounds = find(['rounds','n','iterations','times'])
    if None in (start, a, c, m, rounds):
        # fallback: parse from text field
        text = ''
        for v in inputs.values():
            if isinstance(v, str):
                text += ' ' + v
        nums = list(map(int, re.findall(r'-?\d+', text)))
        if start is None: start = nums[0]
        # attempt heuristic
    X = int(start)
    a = int(a); c = int(c); m = int(m); rounds = int(rounds)
    for _ in range(rounds):
        X = (a * X + c) % m
    return float(X)

