def solve(inputs: dict) -> float:
    import re
    def find(keys):
        for k in keys:
            for kk in inputs:
                if kk.lower() == k:
                    return inputs[kk]
        return None
    start = find(['start','x','x0','initial','value','begin'])
    steps = find(['steps','n','times','iterations','rounds'])
    if start is None or steps is None:
        text = ''
        for v in inputs.values():
            if isinstance(v, str):
                text += ' ' + v
        nums = list(map(int, re.findall(r'-?\d+', text)))
        # heuristic: first big number is start, small around 20 is steps
        if start is None: start = nums[0]
        if steps is None:
            for n in nums[1:]:
                if n < 200: steps = n; break
    X = int(start) & 0xFFFFFFFF
    steps = int(steps)
    mask = 0xFFFFFFFF
    for _ in range(steps):
        X ^= (X << 13) & mask; X &= mask
        X ^= (X >> 9); X &= mask
        X ^= (X << 17) & mask; X &= mask
    return float(X)

