def solve(inputs: dict) -> float:
    import re
    residues = None
    moduli = None
    # try structured
    for k in inputs:
        kl = k.lower()
        if kl in ('residues','remainders','r','a'):
            residues = inputs[k]
        if kl in ('moduli','mods','m','n'):
            moduli = inputs[k]
    if residues is None or moduli is None:
        text = ''
        for v in inputs.values():
            if isinstance(v, str):
                text += ' ' + v
        # find bracketed lists
        lists = re.findall(r'\[([^\]]+)\]', text)
        parsed = [list(map(int, re.findall(r'-?\d+', l))) for l in lists]
        if len(parsed) >= 2:
            residues, moduli = parsed[0], parsed[1]
    residues = [int(x) for x in residues]
    moduli = [int(x) for x in moduli]
    M = 1
    for m in moduli:
        M *= m
    x = 0
    for r, m in zip(residues, moduli):
        Mi = M // m
        inv = pow(Mi, -1, m)
        x += r * Mi * inv
    return float(x % M)

